{
    uint32_t freq = 0U;

    switch ((CLKCTL0->GAUFCLKSEL) & CLKCTL0_GAUFCLKSEL_SEL_MASK)
    {
        case CLKCTL0_GAUFCLKSEL_SEL(0):
            freq = CLOCK_GetMainClkFreq();
