/* Re-enable soft lock for given region */
void IPED_GetRegionAddressRange(FLEXSPI_Type *base,
                                iped_region_t region,
                                uint32_t *start_address,
                                uint32_t *end_address)
{
    __IO uint32_t *reg_start = (__IO uint32_t *)(((uint32_t) & (base->IPEDCTX0START)) + (IPED_CTX_REG_OFFSET * region));
    __IO uint32_t *reg_end   = (__IO uint32_t *)(((uint32_t) & (base->IPEDCTX0END)) + (IPED_CTX_REG_OFFSET * region));

    *start_address = *reg_start & FLEXSPI_IPEDCTX0START_START_ADDRESS_MASK;
    *end_address   = *reg_end & FLEXSPI_IPEDCTX0END_END_ADDRESS_MASK;
}

/* Component ID definition, used by tools. */
status_t IPED_SetRegionAddressRange(FLEXSPI_Type *base,
                                    iped_region_t region,
                                    uint32_t start_address,
                                    uint32_t end_address)
{
    /* Check if region is not locked */
    if (IPED_IsRegionLocked(base, region))
    {
        return (status_t)kStatus_IPED_RegionIsLocked;
    }

    /* Disable soft lock for given region first */
    base->IPEDCTXCTRL[0] = (base->IPEDCTXCTRL[0] & ~(FLEXSPI_IPEDCTXCTRL_CTX0_FREEZE0_MASK << (region * 2UL))) |
                          (IPED_RW_ENABLE_VAL << (region * 2UL));

    __IO uint32_t *reg_start = (__IO uint32_t *)(((uint32_t) & (base->IPEDCTX0START)) + (IPED_CTX_REG_OFFSET * region));
    __IO uint32_t *reg_end   = (__IO uint32_t *)(((uint32_t) & (base->IPEDCTX0END)) + (IPED_CTX_REG_OFFSET * region));

    *reg_start = (*reg_start & (~FLEXSPI_IPEDCTX0START_START_ADDRESS_MASK)) |
                 (start_address & FLEXSPI_IPEDCTX0START_START_ADDRESS_MASK);
    *reg_end =
        (*reg_end & (~FLEXSPI_IPEDCTX0END_END_ADDRESS_MASK)) | (end_address & FLEXSPI_IPEDCTX0END_END_ADDRESS_MASK);

    /* Re-enable soft lock for given region */
    base->IPEDCTXCTRL[0] = (base->IPEDCTXCTRL[0] & ~(FLEXSPI_IPEDCTXCTRL_CTX0_FREEZE0_MASK << (region * 2UL))) |
                           (IPED_RW_DISABLE_VAL << (region * 2UL));

    return kStatus_Success;
}

/* Re-enable soft lock for given region */
status_t IPED_SetRegionEnable(FLEXSPI_Type *base, iped_region_t region, bool enable)
{
    /* Check if region is not locked */
    if (IPED_IsRegionLocked(base, region))
    {
        return (status_t)kStatus_IPED_RegionIsLocked;
    }

    /* Disable soft lock for given region first */
    base->IPEDCTXCTRL[0] = (base->IPEDCTXCTRL[0] & ~(FLEXSPI_IPEDCTXCTRL_CTX0_FREEZE0_MASK << (region * 2UL))) |
                           (IPED_RW_ENABLE_VAL << (region * 2UL));

    __IO uint32_t *reg_start = (__IO uint32_t *)(((uint32_t) & (base->IPEDCTX0START)) + (IPED_CTX_REG_OFFSET * region));
    if (enable)
    {
        *reg_start = *reg_start | FLEXSPI_IPEDCTX0START_GCM_MASK;
    }
    else
    {
        *reg_start = *reg_start & (~FLEXSPI_IPEDCTX0START_GCM_MASK);
    }

    /* Re-enable soft lock for given region */
    base->IPEDCTXCTRL[0] = (base->IPEDCTXCTRL[0] & ~(FLEXSPI_IPEDCTXCTRL_CTX0_FREEZE0_MASK << (region * 2UL))) |
                           (IPED_RW_DISABLE_VAL << (region * 2UL));

    return kStatus_Success;
}

/* Bring SOC OTP out of reset */
status_t OCOTP_OtpFuseRead(uint32_t addr, uint32_t *data)
{
    status_t status = kStatus_InvalidArgument;

    do
    {
        if (data == NULL)
        {
            break;
        }

        status = otp_wait_busy();
        if (status != kStatus_Success)
        {
            break;
        }

        otp_clear_status();

        /* Start reading */
        OCOTP->OTP_CTRL      = OCOTP_OTP_CTRL_ADDR(addr);
        OCOTP->OTP_READ_CTRL = OCOTP_OTP_READ_CTRL_READ(1);

        /* Wait until read completes */
        status = otp_wait_busy();
        if (status != kStatus_Success)
        {
            break;
        }

        /* Check whether errors happened or not. */
        status = otp_get_nonmask_status_result();
        if (status == kStatus_Success)
        {
            *data = OCOTP->OTP_READ_DATA;
        }
    } while (false);

    return status;
}

/* Bring SOC OTP out of reset */
status_t OCOTP_OtpDeinit(void)
{
    status_t status;

    status = otp_wait_busy();
    if (status == kStatus_Success)
    {
        OCOTP->OTP_PDN = OCOTP_OTP_PDN_PDN_MASK;
        CLOCK_DisableClock(kCLOCK_Otp);
    }

    SOC_OTP_CTRL->OTP_POR_B = 0U;
    SOC_OTP_CTRL->OTP_RST_B = 0U;

    return status;
}

/* Write 1s to clear all error status */
status_t OCOTP_OtpInit(void)
{
    CLOCK_EnableClock(kCLOCK_Otp);
    RESET_ClearPeripheralReset(kOTP_RST_SHIFT_RSTn);

    /* Bring SOC OTP out of reset */
    SOC_OTP_CTRL->OTP_POR_B = SOC_OTP_CTRL_OTP_POR_B_OTP_POR_B_MASK;
    SOC_OTP_CTRL->OTP_RST_B = SOC_OTP_CTRL_OTP_RST_B_OTP_RST_B_MASK;

    return kStatus_Success;
}

/* Check whether errors happened or not. */
static uint32_t soc_otp_read(uint32_t addr_line, uint64_t *value)
{
    uint32_t dly                   = SOC_OTP_READ_DELAY_COUNT;
    SOC_OTP_CTRL->OTP_ADDR         = (uint16_t)(addr_line & 0xFFFFU);
    SOC_OTP_CTRL->OTP_BYPASS_MODE1 = 0;
    SOC_OTP_CTRL->OTP_CMD_START    = SOC_OTP_CMD_READ;
    SOC_OTP_CTRL->OTP_CMD_START |= SOC_OTP_CTRL_OTP_CMD_START_OTP_CMD_START_MASK;
    while ((dly > 0U) && ((SOC_OTP_CTRL->OTP_CTRL0 & SOC_OTP_CTRL_OTP_CTRL0_CTRL_CMD_DONE_MASK) == 0U))
    {
        dly--; /* If something horrible happens, bail out after a delay */
    }

    if ((dly > 0U) && ((SOC_OTP_CTRL->OTP_WDATA4 & SOC_OTP_CTRL_OTP_WDATA4_DATA_LINE_VALID_BIT_MASK) != 0U))
    {
        *value = ((uint64_t)SOC_OTP_CTRL->OTP_WDATA3 << 48) | ((uint64_t)SOC_OTP_CTRL->OTP_WDATA2 << 32) |
                 ((uint64_t)SOC_OTP_CTRL->OTP_WDATA1 << 16) | ((uint64_t)SOC_OTP_CTRL->OTP_WDATA0);
        return 1;
    }

    return 0;
}

/*
* Assume core clock is 300MHz, the general fuse operation should not exceed 100ms
* Maximum allowed ticks is 300MHz / 10
* The below loop needs at least 4 CPU cycles, so the timeout rounds for below loop is 300MHz / 10 / 4
*/
static void otp_clear_status(void)
{
    /* Write 1s to clear all error status */
    OCOTP->OTP_STATUS          = OCOTP_OTP_STATUS_PROGFAIL_MASK;
    OCOTP->OTP_NONMASK_STATUS1 = OTP_STATUS1_ERRORS_MASK;
}

/*******************************************************************************
* Code
******************************************************************************/
static status_t otp_wait_busy(void)
{
    /*
     * Assume core clock is 300MHz, the general fuse operation should not exceed 100ms
     * Maximum allowed ticks is 300MHz / 10
     * The below loop needs at least 4 CPU cycles, so the timeout rounds for below loop is 300MHz / 10 / 4
     */
    uint32_t timeout = 300U * 1000U * 1000U / 10U / 4U;
    status_t status;

    while (((OCOTP->OTP_STATUS & OCOTP_OTP_STATUS_BUSY_MASK) != 0U) && (timeout > 0U))
    {
        timeout--;
    }

    if (timeout < 1U)
    {
        status = kStatus_OTP_Timeout;
    }
    else
    {
        status = kStatus_Success;
    }

    return status;
}

/*******************************************************************************
* Code
******************************************************************************/
static status_t otp_get_nonmask_status_result(void)
{
    uint32_t status_register = OCOTP->OTP_NONMASK_STATUS1;
    status_t status;
    int32_t i;

    do
    {
        if ((status_register & OTP_STATUS1_ERRORS_MASK) != 0U)
        {
            for (i = 0; i < 32; i++)
            {
                if (((1UL << (uint32_t)i) & status_register) != 0U)
                {
                    status = MAKE_STATUS(kStatusGroup_OtpGroup, i);
                    break;
                }
            }
        }
        status = kStatus_Success;
    } while (false);

    return status;
}

/* Enable Brown-out Detection */
void POWER_DisableBodMonitor(void)
{
    /* Disable Brown-out Detection and clear interrupt status */
    PMU->BOD = PMU_BOD__1_85_INT_CLR_NEG_MASK;

    /* Disable the related IRQs */
    (void)DisableIRQ(PMIP_IRQn);
    (void)DisableIRQ(PMIP_CHANGE_IRQn);
    /* Clear the callback functions */
    s_bodConfig.drop    = NULL;
    s_bodConfig.recover = NULL;
    s_bodConfig.param   = NULL;
}

/* Restore AON MEM clock/reset */
void POWER_EnableBodMonitor(power_bod_callback drop, power_bod_callback recover, void *userParam)
{
    /* Set the callback functions */
    s_bodConfig.drop    = drop;
    s_bodConfig.recover = recover;
    s_bodConfig.param   = userParam;

    PMU->BOD = PMU_BOD__1_85_INT_CLR_NEG_MASK;
    NVIC_ClearPendingIRQ(PMIP_IRQn);
    NVIC_ClearPendingIRQ(PMIP_CHANGE_IRQn);
    /* Enable the related IRQs */
    (void)EnableIRQ(PMIP_IRQn);
    (void)EnableIRQ(PMIP_CHANGE_IRQn);

    /* Enable Brown-out Detection */
    PMU->BOD = PMU_BOD_EN_MASK;
}

/* Restore ELS reset */
uint32_t POWER_TrimSvc(uint32_t gdetTrim, uint32_t pack)
{
    int32_t x;
    int32_t y1;
    int32_t y3 = 0;
    uint32_t trimSvc = gdetTrim;
    uint32_t clk;
    uint32_t rst;
    uint32_t revision = SOCCTRL->CHIP_INFO & SOCCIU_CHIP_INFO_REV_NUM_MASK;

    if (revision == 2U)
    {
        /* A2 */
        /* Autotrim value at [7:0] */
        x = (int32_t)(uint32_t)(gdetTrim & 0xFFUL);
        if (POWER_SAVED_GDET_CLOCK_SOURCE == POWER_GDET_CLOCK_SOURCE_64MHZ)
        {
            if (pack == 0U)
            {
                /* QFN */
                y1 = (18 * x * x) + (801 * x) + 437290;
                y3 = y1 / 10000;
            }
            else if (pack == 1U)
            {
                /* CSP */
                y1 = (82 * x * x) - (5171 * x) + 559320;
                y3 = y1 / 10000;
            }
            else
            {
                /* BGA */
                assert(pack == 2U);
                y1 = (25 * x * x) + (1337 * x) + 381140;
                y3 = y1 / 10000;
            }
        }
        else if (POWER_SAVED_GDET_CLOCK_SOURCE == POWER_GDET_CLOCK_SOURCE_32MHZ)
        {
            y1 = (-63 * x * x) + (10961 * x) + 265000;
            y3 = y1 / 10000;
        }
        else
        {
            assert(false);
        }

        trimSvc = (((uint32_t)y3) & 0xFFU) << 24;

        clk = CLKCTL0->PSCCTL0;
        rst = RSTCTL0->PRSTCTL0;
        /* Enable AON MEM clock/reset. */
        CLKCTL0->PSCCTL0_SET  = CLKCTL0_PSCCTL0_SET_AON_MEM_MASK;
        RSTCTL0->PRSTCTL0_CLR = RSTCTL0_PRSTCTL0_CLR_AON_MEM_MASK;
        POWER_WRITE_MEM32(0x4015C00CU, trimSvc);
        /* Restore AON MEM clock/reset */
        CLKCTL0->PSCCTL0  = clk;
        RSTCTL0->PRSTCTL0 = rst;
    }

    return trimSvc;
}

/* Restore ELS reset */
bool POWER_EnableGDetVSensors(void)
{
    uint32_t pscctl0, pscctl1, pscctl2;
    uint32_t rstctl0, rstctl1;
    bool retval = true;

    assert(s_gdetSensorContext.disableCount > INT32_MIN);
    s_gdetSensorContext.disableCount--;

    if (s_gdetSensorContext.disableCount == 0)
    {
        pscctl0 = CLKCTL0->PSCCTL0;
        pscctl1 = CLKCTL0->PSCCTL1;
        pscctl2 = CLKCTL0->PSCCTL2;
        rstctl0 = RSTCTL0->PRSTCTL0;
        rstctl1 = RSTCTL0->PRSTCTL1;

        /* Enable ELS/ITRC clock */
        CLKCTL0->PSCCTL0_SET = CLKCTL0_PSCCTL0_ELS_MASK;
        CLKCTL0->PSCCTL1_SET = CLKCTL0_PSCCTL1_ELS_APB_MASK;
        CLKCTL0->PSCCTL2_SET = CLKCTL0_PSCCTL2_ITRC_MASK;
        /* Clear ELS reset */
        RSTCTL0->PRSTCTL0_CLR = RSTCTL0_PRSTCTL0_ELS_MASK;
        RSTCTL0->PRSTCTL1_CLR = RSTCTL0_PRSTCTL1_ELS_APB_MASK;

        /* Only in the normal flow that GDET_INT_EN is disabled, we will restore GDET config here.
         * An exception is that we call POWER_DisableGDetVSensors() before PM3 and then wake up
         * from ROM. In that case, ELS_INT_ENABLE will be set by ROM again and we shouldn't config
         * GDET here. */
        if (((ELS->ELS_CTRL & ELS_ELS_CTRL_ELS_EN_MASK) != 0U) &&
            (ELS->ELS_INT_ENABLE & ELS_ELS_INT_ENABLE_GDET_INT_EN_MASK) == 0U)
        {
            POWER_RestoreGdetVSensorConfig();
            if ((s_gdetSensorContext.ELS_EN != 0U) && (s_gdetSensorContext.ELS_INT_ENABLE != 0U))
            {
                /* To enable GDET, load function must be configured. */
                if (s_gdetCfgloadFunc == NULL)
                {
                    retval = false;
                }
                else
                {
                    /* GDET config must be loaded correctly for GDET working. */
                    retval = s_gdetCfgloadFunc(&s_gdetCfgData);
                }

                /* Clear GDET errors */
                ELS->ELS_INT_STATUS_CLR =
                    ELS_ELS_INT_STATUS_CLR_INT_CLR_MASK | ELS_ELS_INT_STATUS_CLR_GDET_INT_CLR_MASK;
                ELS->ELS_ERR_STATUS_CLR  = ELS_ELS_ERR_STATUS_CLR_ERR_CLR_MASK;
                ELS->ELS_GDET_EVTCNT_CLR = ELS_ELS_GDET_EVTCNT_CLR_GDET_EVTCNT_CLR_MASK;
                /* Clear Sensor errors */
                SENSOR_CTRL->SEN_CLR_REG = 0x3CU;
                /* Clear ITRC status */
                ITRC->STATUS0 = ITRC->STATUS0;
                ITRC->STATUS1 = ITRC->STATUS1;
                if (retval)
                {
                    ELS->ELS_INT_ENABLE = s_gdetSensorContext.ELS_INT_ENABLE;
                }
            }
        }

        /* Restore ELS/ITRC clock */
        CLKCTL0->PSCCTL0 = pscctl0;
        CLKCTL0->PSCCTL1 = pscctl1;
        CLKCTL0->PSCCTL2 = pscctl2;
        /* Restore ELS reset */
        RSTCTL0->PRSTCTL0 = rstctl0;
        RSTCTL0->PRSTCTL1 = rstctl1;
    }

    return retval;
}

/* Delay 600us */
void POWER_DisableGDetVSensors(void)
{
    uint32_t val;
    uint32_t pscctl0, pscctl1, pscctl2;
    uint32_t rstctl0, rstctl1;

    if (s_gdetSensorContext.disableCount == 0)
    {
        pscctl0 = CLKCTL0->PSCCTL0;
        pscctl1 = CLKCTL0->PSCCTL1;
        pscctl2 = CLKCTL0->PSCCTL2;
        rstctl0 = RSTCTL0->PRSTCTL0;
        rstctl1 = RSTCTL0->PRSTCTL1;

        /* Enable ELS/ITRC clock */
        CLKCTL0->PSCCTL0_SET = CLKCTL0_PSCCTL0_ELS_MASK;
        CLKCTL0->PSCCTL1_SET = CLKCTL0_PSCCTL1_ELS_APB_MASK;
        CLKCTL0->PSCCTL2_SET = CLKCTL0_PSCCTL2_ITRC_MASK;
        /* Clear ELS reset */
        RSTCTL0->PRSTCTL0_CLR = RSTCTL0_PRSTCTL0_ELS_MASK;
        RSTCTL0->PRSTCTL1_CLR = RSTCTL0_PRSTCTL1_ELS_APB_MASK;

        s_gdetSensorContext.ELS_EN = ELS->ELS_CTRL & ELS_ELS_CTRL_ELS_EN_MASK;

        /* Save GDET VSEN config */
        POWER_SaveGdetVSensorConfig();
        if (s_gdetSensorContext.ELS_EN != 0U)
        {
            s_gdetSensorContext.ELS_INT_ENABLE = ELS->ELS_INT_ENABLE;
        }

        /* Disable ITRC interrupts, especially security sensors */
        /* Disable V11 sensor */
        val = SENSOR_CTRL->VSEN_CTRL_1_REG_1 & ~SENSOR_CTRL_VSEN_CTRL_1_REG_1_VSEN_SW_ENABLE_MASK;
        SENSOR_CTRL->VSEN_CTRL_1_REG_1 = val;

        /* Disable V18 sensor */
        val = SENSOR_CTRL->VSEN_CTRL_2_REG_1 & ~SENSOR_CTRL_VSEN_CTRL_2_REG_1_VSEN_SW_ENABLE_MASK;
        SENSOR_CTRL->VSEN_CTRL_2_REG_1 = val;

        /* Disable V33 sensor */
        val = SENSOR_CTRL->VSEN_CTRL_3_REG_1 & ~SENSOR_CTRL_VSEN_CTRL_3_REG_1_VSEN_SW_ENABLE_MASK;
        SENSOR_CTRL->VSEN_CTRL_3_REG_1 = val;

        if (s_gdetSensorContext.ELS_EN != 0U)
        {
            /* Disable CSS_INT_ENABLE[GDET_INT_EN] bit field */
            ELS->ELS_INT_ENABLE &= ~ELS_ELS_INT_ENABLE_GDET_INT_EN_MASK;
        }

        /* Disable aGDET/LVD/HVD interrupts in ITRC */
        val             = ITRC->OUT0_SEL0 & ~ITRC_OUT_SEL_MASK;
        ITRC->OUT0_SEL0 = val | ITRC_OUT_SEL_DISABLE;
        val             = ITRC->OUT1_SEL0 & ~ITRC_OUT_SEL_MASK;
        ITRC->OUT1_SEL0 = val | ITRC_OUT_SEL_DISABLE;

        val                        = ITRC->OUT0_SEL0_EVENT16_31 & ~ITRC_OUT_SEL_EVENT_MASK;
        ITRC->OUT0_SEL0_EVENT16_31 = val | ITRC_OUT_SEL_EVENT_DISABLE;
        val                        = ITRC->OUT1_SEL0_EVENT16_31 & ~ITRC_OUT_SEL_EVENT_MASK;
        ITRC->OUT1_SEL0_EVENT16_31 = val | ITRC_OUT_SEL_EVENT_DISABLE;

        /* Restore ELS/ITRC clock */
        CLKCTL0->PSCCTL0 = pscctl0;
        CLKCTL0->PSCCTL1 = pscctl1;
        CLKCTL0->PSCCTL2 = pscctl2;
        /* Restore ELS reset */
        RSTCTL0->PRSTCTL0 = rstctl0;
        RSTCTL0->PRSTCTL1 = rstctl1;
    }

    assert(s_gdetSensorContext.disableCount < INT32_MAX);
    s_gdetSensorContext.disableCount++;
}

/* Request buck off */
void Power_InitLoadGdetCfg(power_load_gdet_cfg loadFunc, const power_gdet_data_t *data, uint32_t pack)
{
    assert(loadFunc != NULL);
    assert(data != NULL);
    assert(pack <= 2U);

    s_gdetCfgloadFunc = loadFunc;
    (void)memcpy(&s_gdetCfgData, data, sizeof(power_gdet_data_t));
    /* Save GDET clock source on startup */
    s_gdetCfgData.TRIM0  = CLKCTL0->ELS_GDET_CLK_SEL;
    s_gdetCfgData.CFG[3] = POWER_TrimSvc(data->CFG[3], pack);
}

/* Configure voltage threshold */
void POWER_InitVoltage(uint32_t dro, uint32_t pack)
{
    int32_t i;
    uint8_t val;

    SystemCoreClockUpdate();

    /* LPBG trim */
    BUCK11->BUCK_CTRL_EIGHTEEN_REG &= (uint8_t)((~BUCK11_BUCK_CTRL_EIGHTEEN_REG_LPBG_TRIM_MASK) & 0xFFU);

    if (dro == 0U)
    { /* Boot voltage 1.11V */
        val = 0x60U;
    }
    else
    {
        /* Change buck level */
        dro /= 1000U;
        i = 36 - (int32_t)dro;
        assert((i >= 0) && ((uint32_t)i < ARRAY_SIZE(s_droTable)));
        val = s_droTable[i];
    }
    PMU->PMIP_BUCK_LVL = PMU_PMIP_BUCK_LVL_SLEEP_BUCK18_SEL(0x60U) |  /* 1.8V */
                         PMU_PMIP_BUCK_LVL_SLEEP_BUCK11_SEL(0x22U) |  /* 0.8V */
                         PMU_PMIP_BUCK_LVL_NORMAL_BUCK18_SEL(0x60U) | /* 1.8V */
                         PMU_PMIP_BUCK_LVL_NORMAL_BUCK11_SEL(val);
    /* Delay 600us */
    POWER_DelayUs(600U);

    POWER_InitVSensorThreshold(val, pack);
}

