        status = Serial_UsbCdcWrite(((serial_handle_t)&serHandle->lowLevelhandleBuffer[0]), buffer, length);
    }
    else
#endif
#if (defined(SERIAL_PORT_TYPE_SWO) && (SERIAL_PORT_TYPE_SWO > 0U))
        if (kSerialPort_Swo == serHandle->serialPortType) /* Serial port SWO */
    {
        status = Serial_SwoWrite(((serial_handle_t)&serHandle->lowLevelhandleBuffer[0]), buffer, length);
    }
    else
#endif
#if (defined(SERIAL_PORT_TYPE_VIRTUAL) && (SERIAL_PORT_TYPE_VIRTUAL > 0U))
        if (kSerialPort_Virtual == serHandle->serialPortType) /* Serial port UsbCdcVirtual */
    {
        status = Serial_PortVirtualWrite(((serial_handle_t)&serHandle->lowLevelhandleBuffer[0]), buffer, length);
    }
    else
#endif
#if (defined(SERIAL_PORT_TYPE_RPMSG) && (SERIAL_PORT_TYPE_RPMSG > 0U))
        if (kSerialPort_Rpmsg == serHandle->serialPortType) /* Serial port Rpmsg */
    {
        status = Serial_RpmsgWrite(((serial_handle_t)&serHandle->lowLevelhandleBuffer[0]), buffer, length);
    }
    else
#endif
#if (defined(SERIAL_PORT_TYPE_SPI_MASTER) && (SERIAL_PORT_TYPE_SPI_MASTER > 0U))
        if (kSerialPort_SpiMaster == serHandle->serialPortType) /* Serial port Spi Master */
    {
        status = Serial_SpiMasterWrite(((serial_handle_t)&serHandle->lowLevelhandleBuffer[0]), buffer, length);
    }
    else
#endif
#if (defined(SERIAL_PORT_TYPE_BLE_WU) && (SERIAL_PORT_TYPE_BLE_WU > 0U))
        if (kSerialPort_BleWu == serHandle->serialPortType) /* Serial port BLE WU */
    {
        status = Serial_PortBleWuWrite(((serial_handle_t)&serHandle->lowLevelhandleBuffer[0]), buffer, length);
    }
    else
#endif
    {
        /*MISRA rule*/
    }
    return status;
}

/* Component ID definition, used by tools. */
status_t SILICONID_ConvertToMacAddr(uint8_t (*macAddr)[6])
{
    status_t result;

    uint8_t siliconId[SILICONID_MAX_LENGTH];
    uint32_t idLen = sizeof(siliconId);

    result = SILICONID_GetID(&siliconId[0], &idLen);
    if (result != kStatus_Success)
    {
        return result;
    }

    /* Valid ID should > 3. */
    assert(idLen >= 3U);

    /* Set NXP OUI. */
    macAddr[0][0] = 0x54;
    macAddr[0][1] = 0x27;
    macAddr[0][2] = 0x8d;

    /* Set with silicon id. */
    macAddr[0][3] = siliconId[0];
    macAddr[0][4] = siliconId[1];
    macAddr[0][5] = siliconId[2];

    return result;
}

/* Component ID definition, used by tools. */
status_t SILICONID_GetID(uint8_t *siliconId, uint32_t *idLen)
{
    assert((siliconId != NULL) && (idLen != NULL) && (*idLen != 0U));

    status_t result = kStatus_Fail;

#if defined(SIM)
    assert(sizeof(sim_uid_t) <= SILICONID_MAX_LENGTH);
    uint32_t readBytes = *idLen;
    sim_uid_t uid;
    SIM_GetUniqueId(&uid);
    readBytes = (readBytes > sizeof(sim_uid_t)) ? sizeof(sim_uid_t) : readBytes;
    (void)memcpy((void *)&siliconId[0], (void *)(uint8_t *)&uid, readBytes);
    *idLen = readBytes;
    result = kStatus_Success;
#elif defined(FSL_FEATURE_SYSCON_IAP_ENTRY_LOCATION)
    uint32_t readBytes = *idLen;
    uint8_t uid[16];
    result = IAP_ReadUniqueID((uint32_t *)(uintptr_t)&uid[0]);
    if (result == kStatus_Success)
    {
        readBytes = (readBytes > 16U) ? 16U : readBytes;
        (void)memcpy((void *)&siliconId[0], (void *)&uid[0], readBytes);
        *idLen = readBytes;
    }
    else
    {
        *idLen = 0;
    }
#else
    extern status_t SILICONID_ReadUniqueID(uint8_t * siliconId, uint32_t * idLen);
    result = SILICONID_ReadUniqueID(&siliconId[0], idLen);
#endif

    return result;
}

